        } else if (Values.class.isAssignableFrom(clazz)) {
            // TODO can't we figure this out from the function itself?
            types = List.of("Int", "Long", "Double", "Boolean", "BytesRef");
        } else if (Top.class.isAssignableFrom(clazz)) {
            types = List.of("Boolean", "Int", "Long", "Double", "Ip", "BytesRef");
        } else if (Rate.class.isAssignableFrom(clazz) || StdDev.class.isAssignableFrom(clazz)) {
            types = List.of("Int", "Long", "Double");
        } else if (FromPartial.class.isAssignableFrom(clazz) || ToPartial.class.isAssignableFrom(clazz)) {
            types = List.of(""); // no type
        } else if (CountDistinct.class.isAssignableFrom(clazz)) {
            types = Stream.concat(NUMERIC.stream(), Stream.of("Boolean", "BytesRef")).toList();
        } else {
            assert false : "unknown aggregate type " + clazz;
            throw new IllegalArgumentException("unknown aggregate type " + clazz);
        }

final class StExtentStateWrappedLongitudeState implements AggregatorState {
    // Only geo points support longitude wrapping.
    private static final PointType POINT_TYPE = PointType.GEO;
    private boolean seen = false;
    private int minNegX = SpatialAggregationUtils.DEFAULT_NEG;
    private int minPosX = SpatialAggregationUtils.DEFAULT_POS;
    private int maxNegX = SpatialAggregationUtils.DEFAULT_NEG;
    private int maxPosX = SpatialAggregationUtils.DEFAULT_POS;
    private int maxY = Integer.MIN_VALUE;
    private int minY = Integer.MAX_VALUE;

    @Override
    public void close() {}

    @Override
    public void toIntermediate(Block[] blocks, int offset, DriverContext driverContext) {
        assert blocks.length >= offset + 6;
        var blockFactory = driverContext.blockFactory();
        blocks[offset + 0] = blockFactory.newConstantIntBlockWith(minNegX, 1);
        blocks[offset + 1] = blockFactory.newConstantIntBlockWith(minPosX, 1);
        blocks[offset + 2] = blockFactory.newConstantIntBlockWith(maxNegX, 1);
        blocks[offset + 3] = blockFactory.newConstantIntBlockWith(maxPosX, 1);
        blocks[offset + 4] = blockFactory.newConstantIntBlockWith(maxY, 1);
        blocks[offset + 5] = blockFactory.newConstantIntBlockWith(minY, 1);
    }

    public void add(Geometry geo) {
        var geoPointVisitor = new SpatialEnvelopeVisitor.GeoPointVisitor(true /*wrapLongitude*/);
        if (geo.visit(new SpatialEnvelopeVisitor(geoPointVisitor))) {
            add(
                SpatialAggregationUtils.encodeNegativeLongitude(geoPointVisitor.getMinNegX()),
                SpatialAggregationUtils.encodePositiveLongitude(geoPointVisitor.getMinPosX()),
                SpatialAggregationUtils.encodeNegativeLongitude(geoPointVisitor.getMaxNegX()),
                SpatialAggregationUtils.encodePositiveLongitude(geoPointVisitor.getMaxPosX()),
                POINT_TYPE.encodeY(geoPointVisitor.getMaxY()),
                POINT_TYPE.encodeY(geoPointVisitor.getMinY())
            );
        }
    }

    public void add(int minNegX, int minPosX, int maxNegX, int maxPosX, int maxY, int minY) {
        seen = true;
        this.minNegX = Math.min(this.minNegX, minNegX);
        this.minPosX = SpatialAggregationUtils.minPos(this.minPosX, minPosX);
        this.maxNegX = SpatialAggregationUtils.maxNeg(this.maxNegX, maxNegX);
        this.maxPosX = Math.max(this.maxPosX, maxPosX);
        this.maxY = Math.max(this.maxY, maxY);
        this.minY = Math.min(this.minY, minY);
        assert this.minNegX <= 0 == this.maxNegX <= 0 : "minNegX=" + this.minNegX + " maxNegX=" + this.maxNegX;
        assert this.minPosX >= 0 == this.maxPosX >= 0 : "minPosX=" + this.minPosX + " maxPosX=" + this.maxPosX;
    }

    public void add(long encoded) {
        int x = POINT_TYPE.extractX(encoded);
        int y = POINT_TYPE.extractY(encoded);
        add(x, x, x, x, y, y);
    }

    public Block toBlock(DriverContext driverContext) {
        var factory = driverContext.blockFactory();
        return seen ? factory.newConstantBytesRefBlockWith(new BytesRef(toWKB()), 1) : factory.newConstantNullBlock(1);
    }

    private byte[] toWKB() {
        return WellKnownBinary.toWKB(
            SpatialAggregationUtils.getResult(minNegX, minPosX, maxNegX, maxPosX, maxY, minY),
            ByteOrder.LITTLE_ENDIAN
        );
    }
}

final class StExtentGroupingStateWrappedLongitudeState extends AbstractArrayState implements GroupingAggregatorState {
    // Only geo points support longitude wrapping.
    private static final PointType POINT_TYPE = PointType.GEO;
    private IntArray minNegXs;
    private IntArray minPosXs;
    private IntArray maxNegXs;
    private IntArray maxPosXs;
    private IntArray maxYs;
    private IntArray minYs;

    StExtentGroupingStateWrappedLongitudeState() {
        this(BigArrays.NON_RECYCLING_INSTANCE);
    }

    StExtentGroupingStateWrappedLongitudeState(BigArrays bigArrays) {
        super(bigArrays);
        this.minNegXs = bigArrays.newIntArray(0, false);
        this.minPosXs = bigArrays.newIntArray(0, false);
        this.maxNegXs = bigArrays.newIntArray(0, false);
        this.maxPosXs = bigArrays.newIntArray(0, false);
        this.maxYs = bigArrays.newIntArray(0, false);
        this.minYs = bigArrays.newIntArray(0, false);
        enableGroupIdTracking(new SeenGroupIds.Empty());
    }

    @Override
    public void toIntermediate(Block[] blocks, int offset, IntVector selected, DriverContext driverContext) {
        assert blocks.length >= offset;
        try (
            var minNegXsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
            var minPosXsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
            var maxNegXsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
            var maxPosXsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
            var maxYsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
            var minYsBuilder = driverContext.blockFactory().newIntBlockBuilder(selected.getPositionCount());
        ) {
            for (int i = 0; i < selected.getPositionCount(); i++) {
                int group = selected.getInt(i);
                assert hasValue(group);
                assert minNegXs.get(group) <= 0 == maxNegXs.get(group) <= 0;
                assert minPosXs.get(group) >= 0 == maxPosXs.get(group) >= 0;
                minNegXsBuilder.appendInt(minNegXs.get(group));
                minPosXsBuilder.appendInt(minPosXs.get(group));
                maxNegXsBuilder.appendInt(maxNegXs.get(group));
                maxPosXsBuilder.appendInt(maxPosXs.get(group));
                maxYsBuilder.appendInt(maxYs.get(group));
                minYsBuilder.appendInt(minYs.get(group));
            }
            blocks[offset + 0] = minNegXsBuilder.build();
            blocks[offset + 1] = minPosXsBuilder.build();
            blocks[offset + 2] = maxNegXsBuilder.build();
            blocks[offset + 3] = maxPosXsBuilder.build();
            blocks[offset + 4] = maxYsBuilder.build();
            blocks[offset + 5] = minYsBuilder.build();
        }
    }

    public void add(int groupId, Geometry geo) {
        ensureCapacity(groupId);
        var geoPointVisitor = new SpatialEnvelopeVisitor.GeoPointVisitor(true /*wrapLongitude*/);
        if (geo.visit(new SpatialEnvelopeVisitor(geoPointVisitor))) {
            add(
                groupId,
                SpatialAggregationUtils.encodeNegativeLongitude(geoPointVisitor.getMinNegX()),
                SpatialAggregationUtils.encodePositiveLongitude(geoPointVisitor.getMinPosX()),
                SpatialAggregationUtils.encodeNegativeLongitude(geoPointVisitor.getMaxNegX()),
                SpatialAggregationUtils.encodePositiveLongitude(geoPointVisitor.getMaxPosX()),
                POINT_TYPE.encodeY(geoPointVisitor.getMaxY()),
                POINT_TYPE.encodeY(geoPointVisitor.getMinY())
            );
        }
    }

    public void add(int groupId, StExtentGroupingStateWrappedLongitudeState inState, int inPosition) {
        ensureCapacity(groupId);
        if (inState.hasValue(inPosition)) {
            add(
                groupId,
                inState.minNegXs.get(inPosition),
                inState.minPosXs.get(inPosition),
                inState.maxNegXs.get(inPosition),
                inState.maxPosXs.get(inPosition),
                inState.maxYs.get(inPosition),
                inState.minYs.get(inPosition)
            );
        }
    }

    public void add(int groupId, long encoded) {
        int x = POINT_TYPE.extractX(encoded);
        int y = POINT_TYPE.extractY(encoded);
        add(groupId, x, x, x, x, y, y);
    }

    public void add(int groupId, int minNegX, int minPosX, int maxNegX, int maxPosX, int maxY, int minY) {
        ensureCapacity(groupId);
        if (hasValue(groupId)) {
            minNegXs.set(groupId, Math.min(minNegXs.get(groupId), minNegX));
            minPosXs.set(groupId, SpatialAggregationUtils.minPos(minPosXs.get(groupId), minPosX));
            maxNegXs.set(groupId, SpatialAggregationUtils.maxNeg(maxNegXs.get(groupId), maxNegX));
            maxPosXs.set(groupId, Math.max(maxPosXs.get(groupId), maxPosX));
            maxYs.set(groupId, Math.max(maxYs.get(groupId), maxY));
            minYs.set(groupId, Math.min(minYs.get(groupId), minY));
        } else {
            minNegXs.set(groupId, minNegX);
            minPosXs.set(groupId, minPosX);
            maxNegXs.set(groupId, maxNegX);
            maxPosXs.set(groupId, maxPosX);
            maxYs.set(groupId, maxY);
            minYs.set(groupId, minY);
        }
        assert minNegX <= 0 == maxNegX <= 0 : "minNegX=" + minNegX + " maxNegX=" + maxNegX;
        assert minPosX >= 0 == maxPosX >= 0 : "minPosX=" + minPosX + " maxPosX=" + maxPosX;
        trackGroupId(groupId);
    }

    private void ensureCapacity(int groupId) {
        long requiredSize = groupId + 1;
        if (minNegXs.size() < requiredSize) {
            minNegXs = bigArrays.grow(minNegXs, requiredSize);
            minPosXs = bigArrays.grow(minPosXs, requiredSize);
            maxNegXs = bigArrays.grow(maxNegXs, requiredSize);
            maxPosXs = bigArrays.grow(maxPosXs, requiredSize);
            minYs = bigArrays.grow(minYs, requiredSize);
            maxYs = bigArrays.grow(maxYs, requiredSize);
        }
    }

    public Block toBlock(IntVector selected, DriverContext driverContext) {
        try (var builder = driverContext.blockFactory().newBytesRefBlockBuilder(selected.getPositionCount())) {
            for (int i = 0; i < selected.getPositionCount(); i++) {
                int si = selected.getInt(i);
                if (hasValue(si)) {
                    builder.appendBytesRef(
                        new BytesRef(
                            WellKnownBinary.toWKB(
                                SpatialAggregationUtils.getResult(
                                    minNegXs.get(si),
                                    minPosXs.get(si),
                                    maxNegXs.get(si),
                                    maxPosXs.get(si),
                                    maxYs.get(si),
                                    minYs.get(si)
                                ),
                                ByteOrder.LITTLE_ENDIAN
                            )
                        )
                    );
                } else {
                    builder.appendNull();
                }
            }
            return builder.build();
        }
    }
}

/**
 * This aggregator calculates the centroid of a set of geo points. It is assumes that the geo points are encoded as longs.
 * This requires that the planner has planned that points are loaded from the index as doc-values.
 */
@Aggregator(
    {
        @IntermediateState(name = "xVal", type = "DOUBLE"),
        @IntermediateState(name = "xDel", type = "DOUBLE"),
        @IntermediateState(name = "yVal", type = "DOUBLE"),
        @IntermediateState(name = "yDel", type = "DOUBLE"),
        @IntermediateState(name = "count", type = "LONG") }
)
@GroupingAggregator
class SpatialCentroidGeoPointDocValuesAggregator extends CentroidPointAggregator {

    public static CentroidState initSingle() {
        return new CentroidState();
    }

    public static GroupingCentroidState initGrouping(BigArrays bigArrays) {
        return new GroupingCentroidState(bigArrays);
    }

    public static void combine(CentroidState current, long v) {
        current.add(decodeX(v), decodeY(v));
    }

    public static void combine(GroupingCentroidState current, int groupId, long encoded) {
        current.add(decodeX(encoded), 0d, decodeY(encoded), 0d, 1, groupId);
    }

    private static double decodeX(long encoded) {
        return GeoEncodingUtils.decodeLongitude((int) (encoded & 0xFFFFFFFFL));
    }

    private static double decodeY(long encoded) {
        return GeoEncodingUtils.decodeLatitude((int) (encoded >>> 32));
    }
}

/**
 * This aggregator calculates the centroid of a set of geo points or cartesian_points.
 * It is assumes that the points are encoded as longs.
 * This requires that the planner has planned that points are loaded from the index as doc-values.
 */
abstract class CentroidPointAggregator {
    public static CentroidState initSingle() {
        return new CentroidState();
    }

    public static GroupingCentroidState initGrouping(BigArrays bigArrays) {
        return new GroupingCentroidState(bigArrays);
    }

    public static void combine(CentroidState current, double xVal, double xDel, double yVal, double yDel, long count) {
        current.add(xVal, xDel, yVal, yDel, count);
    }

    public static void combineStates(CentroidState current, CentroidState state) {
        current.add(state);
    }

    public static void combineIntermediate(CentroidState state, double xIn, double dx, double yIn, double dy, long count) {
        if (count > 0) {
            combine(state, xIn, dx, yIn, dy, count);
        }
    }

    public static void evaluateIntermediate(CentroidState state, DriverContext driverContext, Block[] blocks, int offset) {
        assert blocks.length >= offset + 5;
        BlockFactory blockFactory = driverContext.blockFactory();
        blocks[offset + 0] = blockFactory.newConstantDoubleBlockWith(state.xSum.value(), 1);
        blocks[offset + 1] = blockFactory.newConstantDoubleBlockWith(state.xSum.delta(), 1);
        blocks[offset + 2] = blockFactory.newConstantDoubleBlockWith(state.ySum.value(), 1);
        blocks[offset + 3] = blockFactory.newConstantDoubleBlockWith(state.ySum.delta(), 1);
        blocks[offset + 4] = blockFactory.newConstantLongBlockWith(state.count, 1);
    }

    public static Block evaluateFinal(CentroidState state, DriverContext driverContext) {
        return state.toBlock(driverContext.blockFactory());
    }

    public static void combineStates(GroupingCentroidState current, int groupId, GroupingCentroidState state, int statePosition) {
        if (state.hasValue(statePosition)) {
            current.add(
                state.xValues.get(statePosition),
                state.xDeltas.get(statePosition),
                state.yValues.get(statePosition),
                state.yDeltas.get(statePosition),
                state.counts.get(statePosition),
                groupId
            );
        }
    }

    public static void combineIntermediate(
        GroupingCentroidState current,
        int groupId,
        double xValue,
        double xDelta,
        double yValue,
        double yDelta,
        long count
    ) {
        if (count > 0) {
            current.add(xValue, xDelta, yValue, yDelta, count, groupId);
        }
    }

    public static void evaluateIntermediate(
        GroupingCentroidState state,
        Block[] blocks,
        int offset,
        IntVector selected,
        DriverContext driverContext
    ) {
        assert blocks.length >= offset + 5;
        try (
            var xValuesBuilder = driverContext.blockFactory().newDoubleBlockBuilder(selected.getPositionCount());
            var xDeltaBuilder = driverContext.blockFactory().newDoubleBlockBuilder(selected.getPositionCount());
            var yValuesBuilder = driverContext.blockFactory().newDoubleBlockBuilder(selected.getPositionCount());
            var yDeltaBuilder = driverContext.blockFactory().newDoubleBlockBuilder(selected.getPositionCount());
            var countsBuilder = driverContext.blockFactory().newLongBlockBuilder(selected.getPositionCount());
        ) {
            for (int i = 0; i < selected.getPositionCount(); i++) {
                int group = selected.getInt(i);
                if (group < state.xValues.size()) {
                    xValuesBuilder.appendDouble(state.xValues.get(group));
                    xDeltaBuilder.appendDouble(state.xDeltas.get(group));
                    yValuesBuilder.appendDouble(state.yValues.get(group));
                    yDeltaBuilder.appendDouble(state.yDeltas.get(group));
                    countsBuilder.appendLong(state.counts.get(group));
                } else {
                    xValuesBuilder.appendDouble(0);
                    xDeltaBuilder.appendDouble(0);
                    yValuesBuilder.appendDouble(0);
                    yDeltaBuilder.appendDouble(0);
                    countsBuilder.appendLong(0);
                }
            }
            blocks[offset + 0] = xValuesBuilder.build();
            blocks[offset + 1] = xDeltaBuilder.build();
            blocks[offset + 2] = yValuesBuilder.build();
            blocks[offset + 3] = yDeltaBuilder.build();
            blocks[offset + 4] = countsBuilder.build();
        }
    }

    public static Block evaluateFinal(GroupingCentroidState state, IntVector selected, DriverContext driverContext) {
        try (BytesRefBlock.Builder builder = driverContext.blockFactory().newBytesRefBlockBuilder(selected.getPositionCount())) {
            for (int i = 0; i < selected.getPositionCount(); i++) {
                int si = selected.getInt(i);
                if (state.hasValue(si) && si < state.xValues.size()) {
                    BytesRef result = state.encodeCentroidResult(si);
                    builder.appendBytesRef(result);
                } else {
                    builder.appendNull();
                }
            }
            return builder.build();
        }
    }

    private static BytesRef encode(double x, double y) {
        return new BytesRef(WellKnownBinary.toWKB(new Point(x, y), ByteOrder.LITTLE_ENDIAN));
    }

    static class CentroidState implements AggregatorState {
        protected final CompensatedSum xSum = new CompensatedSum(0, 0);
        protected final CompensatedSum ySum = new CompensatedSum(0, 0);
        protected long count = 0;

        @Override
        public void toIntermediate(Block[] blocks, int offset, DriverContext driverContext) {
            CentroidPointAggregator.evaluateIntermediate(this, driverContext, blocks, offset);
        }

        @Override
        public void close() {}

        public void count(long count) {
            this.count = count;
        }

        public void add(CentroidState other) {
            xSum.add(other.xSum.value(), other.xSum.delta());
            ySum.add(other.ySum.value(), other.ySum.delta());
            count += other.count;
        }

        public void add(double x, double y) {
            xSum.add(x);
            ySum.add(y);
            count++;
        }

        public void add(double x, double dx, double y, double dy, long count) {
            xSum.add(x, dx);
            ySum.add(y, dy);
            this.count += count;
        }

        protected Block toBlock(BlockFactory blockFactory) {
            if (count > 0) {
                double x = xSum.value() / count;
                double y = ySum.value() / count;
                return blockFactory.newConstantBytesRefBlockWith(encode(x, y), 1);
            } else {
                return blockFactory.newConstantNullBlock(1);
            }
        }
    }

    static class GroupingCentroidState implements GroupingAggregatorState {
        private final BigArrays bigArrays;

        DoubleArray xValues;
        DoubleArray xDeltas;
        DoubleArray yValues;
        DoubleArray yDeltas;

        LongArray counts;

        GroupingCentroidState(BigArrays bigArrays) {
            this.bigArrays = bigArrays;
            boolean success = false;
            try {
                this.xValues = bigArrays.newDoubleArray(1);
                this.xDeltas = bigArrays.newDoubleArray(1);
                this.yValues = bigArrays.newDoubleArray(1);
                this.yDeltas = bigArrays.newDoubleArray(1);
                this.counts = bigArrays.newLongArray(1);
                success = true;
            } finally {
                if (success == false) {
                    close();
                }
            }
        }

        void add(double x, double dx, double y, double dy, long count, int groupId) {
            ensureCapacity(groupId);

            // If the value is Inf or NaN, just add it to the running tally to "convert" to
            // Inf/NaN. This keeps the behavior bwc from before kahan summing
            if (Double.isFinite(x) == false || Double.isFinite(y) == false) {
                xValues.increment(groupId, x);
                yValues.increment(groupId, y);
                return;
            }

            addTo(xValues, xDeltas, groupId, x, dx);
            addTo(yValues, yDeltas, groupId, y, dy);
            counts.increment(groupId, count);
        }

        private static void addTo(DoubleArray values, DoubleArray deltas, int groupId, double valueToAdd, double deltaToAdd) {
            double value = values.get(groupId);
            if (Double.isFinite(value) == false) {
                // It isn't going to get any more infinite.
                return;
            }
            double delta = deltas.get(groupId);
            double correctedSum = valueToAdd + (delta + deltaToAdd);
            double updatedValue = value + correctedSum;
            deltas.set(groupId, correctedSum - (updatedValue - value));
            values.set(groupId, updatedValue);
        }

        boolean hasValue(int index) {
            return counts.get(index) > 0;
        }

        /** Needed for generated code that does null tracking, which we do not need because we use count */
        final void enableGroupIdTracking(SeenGroupIds ignore) {}

        private void ensureCapacity(int groupId) {
            if (groupId >= xValues.size()) {
                xValues = bigArrays.grow(xValues, groupId + 1);
                xDeltas = bigArrays.grow(xDeltas, groupId + 1);
                yValues = bigArrays.grow(yValues, groupId + 1);
                yDeltas = bigArrays.grow(yDeltas, groupId + 1);
                counts = bigArrays.grow(counts, groupId + 1);
            }
        }

        protected BytesRef encodeCentroidResult(int si) {
            long count = counts.get(si);
            double x = xValues.get(si) / count;
            double y = yValues.get(si) / count;
            return encode(x, y);
        }

        @Override
        public void toIntermediate(Block[] blocks, int offset, IntVector selected, DriverContext driverContext) {
            CentroidPointAggregator.evaluateIntermediate(this, blocks, offset, selected, driverContext);
        }

        @Override
        public void close() {
            Releasables.close(xValues, xDeltas, yValues, yDeltas, counts);
        }
    }
}

/**
 * This aggregator calculates the centroid of a set of cartesian points.
 * It is assumes that the cartesian points are encoded as WKB BytesRef.
 * This requires that the planner has NOT planned that points are loaded from the index as doc-values, but from source instead.
 * This is also used for final aggregations and aggregations in the coordinator node,
 * even if the local node partial aggregation is done with {@link SpatialCentroidCartesianPointSourceValuesAggregator}.
 */
@Aggregator(
    {
        @IntermediateState(name = "xVal", type = "DOUBLE"),
        @IntermediateState(name = "xDel", type = "DOUBLE"),
        @IntermediateState(name = "yVal", type = "DOUBLE"),
        @IntermediateState(name = "yDel", type = "DOUBLE"),
        @IntermediateState(name = "count", type = "LONG") }
)
@GroupingAggregator
class SpatialCentroidCartesianPointSourceValuesAggregator extends CentroidPointAggregator {

    public static CentroidState initSingle() {
        return new CentroidState();
    }

    public static GroupingCentroidState initGrouping(BigArrays bigArrays) {
        return new GroupingCentroidState(bigArrays);
    }

    public static void combine(CentroidState current, BytesRef wkb) {
        Point point = decode(wkb);
        current.add(point.getX(), point.getY());
    }

    public static void combine(GroupingCentroidState current, int groupId, BytesRef wkb) {
        Point point = decode(wkb);
        current.add(point.getX(), 0d, point.getY(), 0d, 1, groupId);
    }

    private static Point decode(BytesRef wkb) {
        return (Point) WellKnownBinary.fromWKB(GeometryValidator.NOOP, false, wkb.bytes, wkb.offset, wkb.length);
    }
}

